            <path d="M145 140 Q250 140 370 100" fill="none" stroke="currentColor" stroke-width="1" stroke-dasharray="5,3" opacity="0.6"/>
            <line x1="380" y1="15" x2="380" y2="185" stroke="currentColor" stroke-width="2"/>
            <text x="388" y="100" font-size="11" fill="currentColor">屏</text>
            <rect x="377" y="88" width="6" height="24" fill="currentColor" opacity="0.9"/>
            <rect x="377" y="55" width="6" height="12" fill="currentColor" opacity="0.4"/>
            <rect x="377" y="133" width="6" height="12" fill="currentColor" opacity="0.4"/>
        </svg>
        <p>归一化光强公式：I<sub>N</sub>(η) = sinc²(πaη/λ) · cos²(πdη/λ)</p>
        <p>其中 sinc(t) = sin(t)/t，sinc(0) = 1；η = (u−u₀)/(4·D<sub>sim</sub>·Z)</p>
    </div>
</div>

<script id="phy-sim-script">
(function() {
'use strict';

var DEFAULTS = { wavelength: 550, slitSeparation: 5000, slitWidth: 1000, screenDistance: 50, zoom: 1 };
var LIMITS = { wavelength: [380,750], slitSeparation: [1000,10000], slitWidth: [200,3000], screenDistance: [1,100], zoom: [1,5] };
var KEYS = ['wavelength','slitSeparation','slitWidth','screenDistance','zoom'];
var ETA_REF = 0.11;

var state = { wavelength:550, slitSeparation:5000, slitWidth:1000, screenDistance:50, zoom:1 };
var theme = 'light';
var palette = 'color';
var compact = false;
var cursorX = null;
var readyResolve = null;
var readyPromise = new Promise(function(r){ readyResolve = r; });
var firstFrameDone = false;

function normalizeParams(p) {
    var out = {};
    for (var i = 0; i < KEYS.length; i++) {
        var k = KEYS[i];
        var v = (p && typeof p[k] === 'number') ? p[k] : NaN;
        if (!isFinite(v)) v = DEFAULTS[k];
        var lo = LIMITS[k][0], hi = LIMITS[k][1];
        if (v < lo) v = lo;
        if (v > hi) v = hi;
        out[k] = v;
    }
    if (out.slitWidth > out.slitSeparation) out.slitWidth = out.slitSeparation;
    return out;
}

function sinc(t) {
    if (t === 0) return 1;
    return Math.sin(t) / t;
}

function intensityAtEta(eta, params) {
    var p = params || state;
    var lam = p.wavelength, a = p.slitWidth, d = p.slitSeparation;
    var tSinc = Math.PI * a * eta / lam;
    var tCos = Math.PI * d * eta / lam;
    var s = sinc(tSinc);
    var c = Math.cos(tCos);
    return s * s * c * c;
}

function etaFromX(x, cssWidth, params) {
    var p = params || state;
    return (x - cssWidth / 2) / (4 * p.screenDistance * p.zoom);
}

function wavelengthToRGB(wl) {
    var r=0,g=0,b=0;
    if (wl>=380&&wl<440){r=-(wl-440)/60;b=1;}
    else if(wl>=440&&wl<490){g=(wl-440)/50;b=1;}
    else if(wl>=490&&wl<510){g=1;b=-(wl-510)/20;}
    else if(wl>=510&&wl<580){r=(wl-510)/70;g=1;}
    else if(wl>=580&&wl<645){r=1;g=-(wl-645)/65;}
    else if(wl>=645&&wl<=750){r=1;}
    return [Math.round(r*255),Math.round(g*255),Math.round(b*255)];
}

function getCriticalMarkers(params) {
    var p = params ? normalizeParams(params) : { wavelength: state.wavelength, slitSeparation: state.slitSeparation, slitWidth: state.slitWidth, screenDistance: state.screenDistance, zoom: state.zoom };
    var wlMarkers = [];
    var dMarkers = [];
    var d = p.slitSeparation;
    var lam = p.wavelength;
    var m, val;
    for (m = 1; m <= 30; m++) {
        val = d * ETA_REF / m;
        if (val >= 380 && val <= 750) {
            wlMarkers.push({kind:'bright', order:m, value:Math.round(val*100)/100});
        }
    }
    for (m = 0; m <= 30; m++) {
        val = d * ETA_REF / (m + 0.5);
        if (val >= 380 && val <= 750) {
            wlMarkers.push({kind:'dark', order:m+0.5, value:Math.round(val*100)/100});
        }
    }
    for (m = 1; m <= 60; m++) {
        val = m * lam / ETA_REF;
        if (val >= 1000 && val <= 10000) {
            dMarkers.push({kind:'bright', order:m, value:Math.round(val*100)/100});
        }
    }
    for (m = 0; m <= 60; m++) {
        val = (m + 0.5) * lam / ETA_REF;
        if (val >= 1000 && val <= 10000) {
            dMarkers.push({kind:'dark', order:m+0.5, value:Math.round(val*100)/100});
        }
    }
    return { wavelength: wlMarkers, slitSeparation: dMarkers };
}

var els = {};
function cacheDom() {
    els.wavelengthInput = document.getElementById('wavelength');
    els.slitSeparationInput = document.getElementById('slitSeparation');
    els.slitWidthInput = document.getElementById('slitWidth');
    els.screenDistanceInput = document.getElementById('screenDistance');
    els.zoomInput = document.getElementById('zoom');
    els.wavelengthOutput = document.getElementById('wavelength-output');
    els.slitSeparationOutput = document.getElementById('slitSeparation-output');
    els.slitWidthOutput = document.getElementById('slitWidth-output');
    els.screenDistanceOutput = document.getElementById('screenDistance-output');
    els.zoomOutput = document.getElementById('zoom-output');
    els.wavelengthMarkers = document.getElementById('wavelength-markers');
    els.slitSeparationMarkers = document.getElementById('slitSeparation-markers');
    els.patternCanvas = document.getElementById('interferenceCanvas');
    els.intensityCanvas = document.getElementById('intensityCanvas');
    els.patternIndicator = document.getElementById('pattern-indicator');
    els.curveIndicator = document.getElementById('curve-indicator');
    els.tooltip = document.getElementById('intensity-tooltip');
    els.curveContainer = document.getElementById('curve-container');
    els.modal = document.getElementById('principle-modal');
    els.modalInner = els.modal ? els.modal.querySelector('[role="dialog"]') : null;
    els.resetBtn = document.getElementById('reset-button');
    els.themeBtn = document.getElementById('theme-button');
    els.paletteBtn = document.getElementById('palette-button');
    els.principleBtn = document.getElementById('principle-button');
    els.modalCloseBtn = document.getElementById('modal-close-button');
}

function updateOutputs() {
    els.wavelengthOutput.textContent = Math.round(state.wavelength) + ' nm';
    els.slitSeparationOutput.textContent = Math.round(state.slitSeparation) + ' nm';
    els.slitWidthOutput.textContent = Math.round(state.slitWidth) + ' nm';
    els.screenDistanceOutput.textContent = Math.round(state.screenDistance);
    els.zoomOutput.textContent = state.zoom.toFixed(1) + '×';
}

function updateInputs() {
    els.wavelengthInput.value = state.wavelength;
    els.slitSeparationInput.value = state.slitSeparation;
    els.slitWidthInput.value = state.slitWidth;
    els.screenDistanceInput.value = state.screenDistance;
    els.zoomInput.value = state.zoom;
}

function renderMarkers() {
    var markers = getCriticalMarkers(state);
    renderMarkerSet(els.wavelengthMarkers, markers.wavelength, LIMITS.wavelength);
    renderMarkerSet(els.slitSeparationMarkers, markers.slitSeparation, LIMITS.slitSeparation);
}

function renderMarkerSet(container, markerList, limits) {
    container.innerHTML = '';
    var lo = limits[0], hi = limits[1];
    for (var i = 0; i < markerList.length; i++) {
        var m = markerList[i];
        var pct = (m.value - lo) / (hi - lo) * 100;
        if (pct < 0 || pct > 100) continue;
        var el = document.createElement('span');
        el.className = 'marker ' + m.kind;
        el.setAttribute('data-kind', m.kind);
        el.style.left = pct + '%';
        el.title = m.kind + ' m=' + m.order + ' @' + m.value;
        container.appendChild(el);
    }
}

function renderPattern() {
    var canvas = els.patternCanvas;
    var container = canvas.parentElement;
    var rect = container.getBoundingClientRect();
    var cssW = rect.width;
    var cssH = rect.height;
    if (cssW < 1 || cssH < 1) return;
    var dpr = window.devicePixelRatio || 1;
    var bw = Math.round(cssW * dpr);
    var bh = Math.round(cssH * dpr);
    if (canvas.width !== bw || canvas.height !== bh) {
        canvas.width = bw;
        canvas.height = bh;
    }
    var ctx = canvas.getContext('2d');
    var imgData = ctx.createImageData(bw, bh);
    var data = imgData.data;
    var baseRGB = wavelengthToRGB(state.wavelength);
    var gamma = 0.45;
    for (var px = 0; px < bw; px++) {
        var cssX = px / dpr;
        var eta = etaFromX(cssX, cssW, state);
        var I = intensityAtEta(eta, state);
        var r, g, b;
        if (palette === 'grayscale') {
            var bright = Math.pow(Math.max(0, Math.min(1, I)), 1.0 / gamma);
            var v = Math.round(bright * 255);
            r = v; g = v; b = v;
        } else {
            var factor = Math.pow(Math.max(0, Math.min(1, I)), 0.8);
            r = Math.round(baseRGB[0] * factor);
            g = Math.round(baseRGB[1] * factor);
            b = Math.round(baseRGB[2] * factor);
        }
        for (var py = 0; py < bh; py++) {
            var idx = (py * bw + px) * 4;
            data[idx] = r;
            data[idx+1] = g;
            data[idx+2] = b;
            data[idx+3] = 255;
        }
    }
    ctx.putImageData(imgData, 0, 0);
}

function renderCurve() {
    var canvas = els.intensityCanvas;
    var container = canvas.parentElement;
    var rect = container.getBoundingClientRect();
    var cssW = rect.width;
    var cssH = rect.height;
    if (cssW < 1 || cssH < 1) return;
    var dpr = window.devicePixelRatio || 1;
    var bw = Math.round(cssW * dpr);
    var bh = Math.round(cssH * dpr);
    if (canvas.width !== bw || canvas.height !== bh) {
        canvas.width = bw;
        canvas.height = bh;
    }
    var ctx = canvas.getContext('2d');
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    var bgColor = getComputedStyle(document.documentElement).getPropertyValue('--canvas-bg').trim() || '#ffffff';
    ctx.fillStyle = bgColor;
    ctx.fillRect(0, 0, cssW, cssH);
    var mTop = 12, mBot = 22;
    var plotH = cssH - mTop - mBot;
    if (plotH < 10) plotH = 10;
    var gridColor = getComputedStyle(document.documentElement).getPropertyValue('--grid-line').trim() || '#eee';
    var axisColor = getComputedStyle(document.documentElement).getPropertyValue('--axis-line').trim() || '#999';
    ctx.strokeStyle = gridColor;
    ctx.lineWidth = 0.5;
    for (var gy = 0; gy <= 4; gy++) {
        var yy = mTop + plotH - (gy / 4) * plotH;
        ctx.beginPath();
        ctx.moveTo(0, yy);
        ctx.lineTo(cssW, yy);
        ctx.stroke();
    }
    ctx.strokeStyle = axisColor;
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(0, mTop + plotH);
    ctx.lineTo(cssW, mTop + plotH);
    ctx.stroke();
    ctx.strokeStyle = axisColor;
    ctx.lineWidth = 0.5;
    ctx.setLineDash([3,3]);
    ctx.beginPath();
    ctx.moveTo(cssW/2, mTop);
    ctx.lineTo(cssW/2, mTop + plotH);
    ctx.stroke();
    ctx.setLineDash([]);
    var curveColor = getComputedStyle(document.documentElement).getPropertyValue('--curve-color').trim() || '#0055cc';
    ctx.strokeStyle = curveColor;
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    var steps = Math.max(Math.round(cssW * 2), 400);
    for (var i = 0; i <= steps; i++) {
        var x = (i / steps) * cssW;
        var eta = etaFromX(x, cssW, state);
        var I = intensityAtEta(eta, state);
        var y = mTop + plotH - I * plotH;
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
    }
    ctx.stroke();
    ctx.fillStyle = axisColor;
    ctx.font = '10px monospace';
